-- ============================================================
-- EX 603 reference dataset: Property Listings / Rental Marketplace
-- Generated deterministically (seed 603). Do not edit by hand.
-- Load with:  createdb ex603_rental && psql -d ex603_rental -f rental.sql
-- ============================================================
-- PostgreSQL load:  createdb ex603_rental  &&  psql -d ex603_rental -f rental.sql
-- (Re-running is safe: every table is dropped first, children before parents.)
DROP TABLE IF EXISTS viewings CASCADE;
DROP TABLE IF EXISTS listing_amenities CASCADE;
DROP TABLE IF EXISTS property_features CASCADE;
DROP TABLE IF EXISTS amenities CASCADE;
DROP TABLE IF EXISTS properties CASCADE;
DROP TABLE IF EXISTS renters CASCADE;

-- ---------- actor ----------
CREATE TABLE renters (
    renter_id        INT           NOT NULL,
    renter_name      VARCHAR(120)  NOT NULL,
    signup_date      DATE          NOT NULL,
    search_city    VARCHAR(80)   NOT NULL,
    email    VARCHAR(160)  NOT NULL,
    referred_by INT           NULL,
    is_active      BOOLEAN       NOT NULL DEFAULT TRUE,
    PRIMARY KEY (renter_id),
    CONSTRAINT uq_renters_email UNIQUE (email),
    CONSTRAINT ck_renters_no_self CHECK (referred_by IS NULL OR referred_by <> renter_id),
    CONSTRAINT fk_renters_ref FOREIGN KEY (referred_by)
        REFERENCES renters (renter_id) ON DELETE SET NULL
);

-- ---------- producer ----------
CREATE TABLE properties (
    property_id        INT           NOT NULL,
    property_label      VARCHAR(120)  NOT NULL,
    listed_on      DATE          NOT NULL,
    city    VARCHAR(80)   NOT NULL,
    listing_code    VARCHAR(60)   NOT NULL,
    monthly_rent    DECIMAL(9,2) NOT NULL,
    is_available      BOOLEAN       NOT NULL DEFAULT TRUE,
    PRIMARY KEY (property_id),
    CONSTRAINT uq_properties_listing_code UNIQUE (listing_code),
    CONSTRAINT ck_properties_metric CHECK (monthly_rent > 0)
);

-- ---------- multivalued attribute, resolved ----------
CREATE TABLE property_features (
    property_id   INT       NOT NULL,
    feature_code  CHAR(2) NOT NULL,
    PRIMARY KEY (property_id, feature_code),
    CONSTRAINT fk_property_features_owner FOREIGN KEY (property_id)
        REFERENCES properties (property_id) ON DELETE CASCADE
);

-- ---------- catalog ----------
CREATE TABLE amenities (
    amenity_id    INT          NOT NULL,
    amenity_name  VARCHAR(60)  NOT NULL,
    amenity_description  VARCHAR(200) NULL,
    PRIMARY KEY (amenity_id),
    CONSTRAINT uq_amenities_name UNIQUE (amenity_name)
);

-- ---------- junction: producer to catalog, composite PK ----------
CREATE TABLE listing_amenities (
    property_id   INT  NOT NULL,
    amenity_id   INT  NOT NULL,
    verified_on DATE NOT NULL,
    PRIMARY KEY (property_id, amenity_id),
    CONSTRAINT fk_listing_amenities_prod FOREIGN KEY (property_id)
        REFERENCES properties (property_id) ON DELETE CASCADE,
    CONSTRAINT fk_listing_amenities_cat FOREIGN KEY (amenity_id)
        REFERENCES amenities (amenity_id) ON DELETE RESTRICT
);

-- ---------- event: the high volume fact table ----------
CREATE TABLE viewings (
    viewing_id       BIGINT        NOT NULL,
    renter_id       INT           NOT NULL,
    property_id       INT           NOT NULL,
    scheduled_at       TIMESTAMP      NOT NULL,
    attended_at      TIMESTAMP      NULL,
    booking_city   VARCHAR(80)   NOT NULL,
    duration_min   DECIMAL(7,2) NOT NULL,
    travel_km   DECIMAL(7,2) NOT NULL,
    interest_score    DECIMAL(4,2)  NOT NULL DEFAULT 1.00,
    viewing_status   VARCHAR(20)   NOT NULL,
    no_show_reason   VARCHAR(60)   NULL,     -- nullable by design
    PRIMARY KEY (viewing_id),
    CONSTRAINT ck_viewings_metric_pos  CHECK (duration_min >= 0),
    CONSTRAINT ck_viewings_second_pos  CHECK (travel_km > 0),
    CONSTRAINT ck_viewings_third_min   CHECK (interest_score >= 1.00),
    CONSTRAINT ck_viewings_time_order  CHECK (attended_at IS NULL OR attended_at >= scheduled_at),
    CONSTRAINT fk_viewings_actor FOREIGN KEY (renter_id)
        REFERENCES renters (renter_id) ON DELETE RESTRICT,
    CONSTRAINT fk_viewings_prod FOREIGN KEY (property_id)
        REFERENCES properties (property_id) ON DELETE RESTRICT
);

